SELECT p.instruction_id FROM phi_inputs p JOIN instructions i ON i.id=p.instruction_id WHERE NOT EXISTS (SELECT 1 FROM control_edges e WHERE e.source_block_id=p.predecessor_block_id AND e.target_block_id=i.block_id) UNION ALL SELECT i.id FROM instructions i WHERE i.opcode='PHI' AND EXISTS (SELECT 1 FROM control_edges e WHERE e.target_block_id=i.block_id AND NOT EXISTS (SELECT 1 FROM phi_inputs p WHERE p.instruction_id=i.id AND p.predecessor_block_id=e.source_block_id));
